10	// recipe; this file is scoped to the `boxedHeader` capability being introduced here, plus the
11	// minimum regression coverage needed to prove the two pre-existing header paths (`title` and
12	// `labelledBy` alone) still behave exactly as before. It is deliberately not a comprehensive suite
13	// for every existing prop (sizes, titleStyle, finalFocusRef/initialFocusRef, etc.).
14	
15	// ZimmIcon throws under Vitest (base SFCC icons barrel side-effect issue — see testing.md's
16	// "Known gap: ZimmIcon throws under Vitest"). ZimmButton's icon variant, rendered for every one of
17	// ZimmDrawer's own close buttons, imports it at module scope, so every test below needs this
18	// mocked regardless of scenario.
19	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
20	
21	// Same technique zimmCountryLanguageMismatch/index.test.tsx uses for the same hook — isolates this
22	// suite from UiCopyProvider's own fetch/lookup logic (covered by its own test coverage) and gives
23	// the close button a fixed, assertable accessible name. Not load-bearing for correctness here —
24	// useUiCopy degrades to the literal fallback ('Close') with no Provider mounted at all (see
25	// useUiCopy.ts) — but kept for consistency with the established pattern elsewhere in this codebase.
26	vi.mock('app/hooks/useUiCopy', () => ({ useUiCopy: vi.fn() }));
27	
28	const mockUseUiCopy = vi.mocked(useUiCopy);
29	const mockT = vi.fn((_key: string, fallback: string) => fallback);
30	
31	const renderDrawer = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);
32	
33	describe('ZimmDrawer', () => {
34	  beforeEach(() => {
35	    mockT.mockImplementation((_key: string, fallback: string) => fallback);
36	    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
37	  });
38	
39	  afterEach(() => {
40	    vi.clearAllMocks();
41	  });
42	
43	  describe('title (regression check — pre-existing path)', () => {
44	    test('renders the in-flow header box; the dialog is named from the title text', () => {
45	      renderDrawer(
46	        <ZimmDrawer isOpen onClose={vi.fn()} size="large" title="SIGN IN">
47	          <p>Body content</p>
48	        </ZimmDrawer>,
49	      );
50	
51	      const dialog = screen.getByRole('dialog', { name: 'SIGN IN' });
52	      expect(dialog).toBeInTheDocument();
53	
54	      const closeButton = screen.getByRole('button', { name: 'Close' });
55	      expect(closeButton).toBeInTheDocument();
56	
57	      // Same structural landmark used for the new boxedHeader case below: a title <span> then the
58	      // close button's own row, sharing one in-flow header box — not the close button alone. One
59	      // level deeper than before the SFCC-831/689 rework: the boxed close button is now wrapped
60	      // in its own `headerCloseButton` part (a real 44px row — see zimmDrawer.css.ts), so this
61	      // walks through that wrapper to reach the shared header box.
62	      const headerBox = closeButton.parentElement?.parentElement;
63	      expect(headerBox?.children).toHaveLength(2);
64	      expect(headerBox?.children[0].tagName).toBe('SPAN');
65	      expect(headerBox?.children[0]).toHaveTextContent('SIGN IN');
66	      // The header part carries no `position` override in zimmDrawer.css.ts (in-flow) — unlike
67	      // the floating closeButton part asserted in the next describe block.
68	      expect(headerBox).not.toHaveStyle({ position: 'absolute' });
69	    });
70	  });
