90	      // button itself) — the boxed treatment always renders a title <span> before it (see the
91	      // title and boxedHeader tests), so its absence is the DOM landmark for "not boxed."
92	      const floatingBox = closeButton.parentElement;
93	      expect(floatingBox?.children).toHaveLength(1);
